const getEnterpriseStringPlan = (panelCount = 0) => {
  const safePanelCount = Math.max(Math.ceil(Number(panelCount) || 0), 1);
  const stringCount = Math.max(
    1,
    Math.ceil(safePanelCount / ENTERPRISE_STRING_PANEL_COUNT),
  );
  const basePanelsPerString = Math.floor(safePanelCount / stringCount);
  const extraPanels = safePanelCount % stringCount;
  const strings = Array.from({ length: stringCount }, (_, index) => ({
    string: index + 1,
    panels: basePanelsPerString + (index < extraPanels ? 1 : 0),
  }));

  return {
    stringCount,
    panelsPerStringReference: ENTERPRISE_STRING_PANEL_COUNT,
    strings,
  };
};

const getEnterpriseHuaweiInverterPlan = (systemSizeKwp = 0) => {
  const targetAcKw = Math.max(
    15,
    Math.ceil(systemSizeKwp / ENTERPRISE_DC_AC_RATIO_TARGET),
  );
  const maxCapacity = Math.max(targetAcKw + 150, 650);
  const dp = Array.from({ length: maxCapacity + 1 }, () => null);
  dp[0] = { cost: 0, items: [] };

  for (let capacity = 0; capacity <= maxCapacity; capacity += 1) {
    const current = dp[capacity];
    if (!current) continue;

    enterpriseHuaweiInverterOptions.forEach((option) => {
      const nextCapacity = Math.min(maxCapacity, capacity + option.capacityKw);
      const nextCost = current.cost + option.totalNet;
      if (!dp[nextCapacity] || nextCost < dp[nextCapacity].cost) {
        dp[nextCapacity] = {
          cost: nextCost,
          items: [...current.items, option],
        };
      }
    });
  }

  const selected = dp
    .map((item, capacity) => ({ ...(item || {}), capacity }))
    .filter((item) => item.items && item.capacity >= targetAcKw)
    .sort((a, b) => a.cost - b.cost || a.capacity - b.capacity)[0];

  const groupedItems = (selected?.items || []).reduce((acc, item) => {
    const key = item.description;
    if (!acc[key]) {
      acc[key] = {
        description: item.description,
        capacityKw: item.capacityKw,
        quantity: 0,
        totalNet: 0,
      };
    }
    acc[key].quantity += 1;
    acc[key].totalNet += item.totalNet;
    return acc;
  }, {});

  const items = Object.values(groupedItems);
  const totalAcKw = items.reduce(
    (sum, item) => sum + item.capacityKw * item.quantity,
    0,
  );
  const totalNet = items.reduce((sum, item) => sum + item.totalNet, 0);

  return {
    targetAcKw,
    totalAcKw,
    totalNet,
    dcAcRatio: systemSizeKwp / Math.max(totalAcKw, 1),
    inverterCount: items.reduce((sum, item) => sum + item.quantity, 0),
    items,
  };
};

const getEnterpriseStructurePlan = (panelCount = 0, surfaceType = "cubierta") => {
  const safePanelCount = Math.max(Math.ceil(Number(panelCount) || 0), 1);
  const isGroundMounted =
    surfaceType === "suelo" ||
    surfaceType === "estacionamiento" ||
    surfaceType === "mixto";
  const requiredAreaM2 =
    safePanelCount * ENTERPRISE_MODULE_DIMENSIONS_M.area * ENTERPRISE_MODULE_SPACING_FACTOR;
  const estimatedRows = Math.max(1, Math.ceil(safePanelCount / 18));
  const portraitPanelBlocks = Math.ceil(safePanelCount / 4);
  const railCount = Math.max(2, portraitPanelBlocks * 2);

  if (isGroundMounted) {
    const biposteSets = Math.ceil(safePanelCount / 2);
    const railConnectors = Math.max(0, railCount - estimatedRows);
    const totalNet =
      biposteSets * enterpriseProductPricesNet.biposteSet +
      railCount * enterpriseProductPricesNet.railBiposte5m +
      railConnectors * enterpriseProductPricesNet.railConnectorBiposte +
      biposteSets * enterpriseProductPricesNet.biposteRearBase +
      Math.ceil(biposteSets / 2) * enterpriseProductPricesNet.biposteAngleTensioner +
      safePanelCount * enterpriseProductPricesNet.groundClip;

    return {
      typeLabel: "Estructura biposte / suelo",
      requiredAreaM2,
      railCount,
      supportCount: biposteSets,
      totalNet,
    };
  }

  const railConnectors = Math.max(0, railCount - estimatedRows);
  const midClamps = Math.max(0, safePanelCount * 2 - estimatedRows * 2);
  const endClamps = estimatedRows * 4;
  const fixingPoints = Math.ceil(safePanelCount * 1.25);
  const totalNet =
    railCount * enterpriseProductPricesNet.railAluminumPro5m +
    railConnectors * enterpriseProductPricesNet.railConnectorPro +
    midClamps * enterpriseProductPricesNet.midClamp30 +
    endClamps * enterpriseProductPricesNet.endClamp30 +
    fixingPoints * enterpriseProductPricesNet.fixingL +
    safePanelCount * enterpriseProductPricesNet.groundClip +
    Math.ceil(safePanelCount / 8) * enterpriseProductPricesNet.groundAnchor;

  return {
    typeLabel: "Estructura sobre cubierta",
    requiredAreaM2,
    railCount,
    supportCount: fixingPoints,
    totalNet,
  };
};

const getEnterpriseCablingPlan = ({
  systemSizeKwp = 0,
  stringCount = 1,
  inverterCount = 1,
} = {}) => {
  const isLargeEnterpriseProject =
    systemSizeKwp >= ENTERPRISE_LARGE_PROJECT_MIN_KWP;
  const dcCableMetersPerPolarity = Math.ceil(
    Math.max(
      isLargeEnterpriseProject
        ? ENTERPRISE_MIN_DC_CABLE_METERS_PER_POLARITY
        : ENTERPRISE_SMALL_PROJECT_MIN_DC_CABLE_METERS_PER_POLARITY,
      stringCount * 35 + inverterCount * 60,
    ),
  );
  const canalizationNet = Math.max(
    isLargeEnterpriseProject
      ? ENTERPRISE_CANALIZATION_MIN_NET
      : ENTERPRISE_SMALL_PROJECT_CANALIZATION_MIN_NET,
    Math.ceil((systemSizeKwp * ENTERPRISE_CANALIZATION_NET_PER_KWP) / 1000) *
      1000,
  );
  const redCableNet =
    dcCableMetersPerPolarity * enterpriseProductPricesNet.cableSolar6mmRedPerMeter;
  const blackCableNet =
    dcCableMetersPerPolarity * enterpriseProductPricesNet.cableSolar6mmBlackPerMeter;
  const mc4Connectors = Math.max(4, stringCount * 4);
  const accessoryBoxes = Math.max(1, Math.ceil(stringCount / 8));
  const accessoriesNet =
    mc4Connectors * enterpriseProductPricesNet.mc4Connector +
    accessoryBoxes * enterpriseProductPricesNet.galvanizedBox150 +
    accessoryBoxes * enterpriseProductPricesNet.lamicoidSheet +
    stringCount * 6 * enterpriseProductPricesNet.cableClipTwo;

  return {
    isLargeEnterpriseProject,
    dcCableMetersPerPolarity,
    redCableNet,
    blackCableNet,
    canalizationNet,
    mc4Connectors,
    accessoryBoxes,
    accessoriesNet,
    totalNet: redCableNet + blackCableNet + canalizationNet + accessoriesNet,
  };
};

const getEnterpriseAcProtectionPlan = (inverterPlan = {}) => {
  const lineItems = [];
  let totalNet = 0;

  (inverterPlan.items || []).forEach((inverter) => {
    let breakerNet = enterpriseProductPricesNet.acBreaker4p40;
    let differentialNet = enterpriseProductPricesNet.diff4p63Si;
    let protectionLabel = "Protección AC trifásica hasta 40 A";

    if (inverter.capacityKw > 30 && inverter.capacityKw <= 50) {
      breakerNet = enterpriseProductPricesNet.acBreaker4p100;
      differentialNet = enterpriseProductPricesNet.diff4p100Si;
      protectionLabel = "Protección AC trifásica hasta 100 A";
    } else if (inverter.capacityKw > 50) {
      breakerNet = enterpriseProductPricesNet.acBreaker4p125;
      differentialNet = enterpriseProductPricesNet.diff4p125Si;
      protectionLabel = "Tablero y protección AC industrial a dimensionar";
    }

    const quantity = Math.max(inverter.quantity, 1);
    totalNet +=
      quantity *
      (breakerNet + differentialNet + enterpriseProductPricesNet.outdoorBoard24p);
    lineItems.push({ description: protectionLabel, quantity });
  });

  totalNet += enterpriseProductPricesNet.smartPowerSensorThreePhase250a;
  lineItems.push({ description: "Smart Power Sensor trifásico", quantity: 1 });

  if ((inverterPlan.inverterCount || 0) > 1 || (inverterPlan.totalAcKw || 0) >= 30) {
    totalNet += enterpriseProductPricesNet.smartLogger3000;
    lineItems.push({ description: "Huawei SmartLogger 3000", quantity: 1 });
  }

  if ((inverterPlan.totalAcKw || 0) >= 100) {
    totalNet += enterpriseProductPricesNet.riRelay;
    lineItems.push({ description: "Relé de interfaz / protección RI", quantity: 1 });
  }

  return { totalNet, items: lineItems };
};

const getEnterpriseProjectExecutionPlan = ({
  communeConfig,
  panelCount = 0,
  systemSizeKwp = 0,
} = {}) => {
  const safeCommune = communeConfig || { roundTripKm: 0, tolls: 0 };
  const travelMetrics = getTravelLogisticsBase(
    safeCommune.roundTripKm,
    safeCommune.tolls,
  );
  const logisticsMode = getProjectLogisticsMode(safeCommune);
  const projectWorkDays = Math.max(
    5,
    Math.ceil(
      Math.max(Number(panelCount) || 0, 1) /
        ENTERPRISE_TECH_CREW_PANEL_CAPACITY_PER_DAY,
    ),
  );
  const travelDays =
    logisticsMode.isRemoteProject && logisticsMode.isLongDistanceRemote
      ? ENTERPRISE_REMOTE_TRAVEL_DAYS
      : 0;
  const bufferDays = logisticsMode.isRemoteProject
    ? Math.max(1, Math.ceil(Math.max(systemSizeKwp - 30, 0) / 100))
    : 0;
  const projectCalendarDays = projectWorkDays + travelDays + bufferDays;
  const crewDailyRate =
    ENTERPRISE_TECH_CREW_LABOR_CLP_PER_DAY +
    ENTERPRISE_HELPER_CREW_LABOR_CLP_PER_DAY;
  const laborNet = projectCalendarDays * crewDailyRate;
  const localLogisticsNet =
    projectCalendarDays * ENTERPRISE_LOCAL_LOGISTICS_CLP_PER_DAY;
  const lodgingNights = logisticsMode.isRemoteProject
    ? Math.max(projectCalendarDays - 1, 1)
    : 0;
  const lodgingNet = lodgingNights * ENTERPRISE_LODGING_CLP_PER_DAY;
  const travelBaseNet = logisticsMode.isRemoteProject
    ? travelMetrics.logisticsBase
    : travelMetrics.logisticsBase * projectWorkDays;
  const travelTimeLaborNet = logisticsMode.isIntermediateProject
    ? getTravelTimeLaborCost({
        oneWayMinutes: logisticsMode.oneWayMinutes,
        projectWorkDays,
        crewDailyRate,
      })
    : 0;
  const logisticsNet =
    travelBaseNet + localLogisticsNet + lodgingNet + travelTimeLaborNet;

  return {
    ...travelMetrics,
    ...logisticsMode,
    projectWorkDays,
    travelDays,
    bufferDays,
    projectCalendarDays,
    laborNet,
    localLogisticsNet,
    lodgingDays: lodgingNights,
    lodgingNights,
    lodgingNet,
    travelBaseNet,
    travelTimeLaborNet,
    logisticsNet,
  };
};

const VEHICLE_EFFICIENCY_KM_PER_L = 8;
const REFERENCE_FUEL_PRICE_CLP_PER_L = 1300;
const VEHICLE_WEAR_CLP_PER_KM = 120;
const BASE_TRAVEL_FEE = 10000;
const TRAVEL_BLOCK_KM = 50;
const TRAVEL_BLOCK_FEE = 20000;
const INSTALLATION_MIN_WORK_DAYS = 5;
const INSTALLATION_PANEL_CREW_CAPACITY_PER_DAY = 8;
const INSTALLATION_REMOTE_TRAVEL_DAYS = 2;
const INSTALLATION_REMOTE_BASE_BUFFER_DAYS = 1;
const INSTALLATION_REMOTE_PANEL_BUFFER_BLOCK = 16;
const INSTALLATION_REMOTE_DISTANCE_BUFFER_THRESHOLD_KM = 1200;
const INSTALLATION_REMOTE_DISTANCE_BUFFER_BLOCK_KM = 800;
const INSTALLATION_TECH_CREW_LABOR_CLP_PER_DAY = 140000;
const INSTALLATION_REMOTE_LODGING_CLP_PER_DAY = 70000;
const INSTALLATION_LOCAL_LOGISTICS_CLP_PER_DAY = 20000;


const getTravelLogisticsBase = (roundTripKm, tolls = 0) => {
  const variableMobilityCostPerKm =
    REFERENCE_FUEL_PRICE_CLP_PER_L / VEHICLE_EFFICIENCY_KM_PER_L +
    VEHICLE_WEAR_CLP_PER_KM;
  const internalTravelEstimate =
    Math.max(roundTripKm, 0) * variableMobilityCostPerKm + tolls;
  const travelBlocks = Math.floor(Math.max(roundTripKm, 0) / TRAVEL_BLOCK_KM);
  const commercialTravelFee = BASE_TRAVEL_FEE + travelBlocks * TRAVEL_BLOCK_FEE;

  return {
    variableMobilityCostPerKm,
    internalTravelEstimate,
    travelBlocks,
    commercialTravelFee,
    logisticsBase: Math.max(internalTravelEstimate, commercialTravelFee),
  };
};

const getProjectLogisticsMode = (communeConfig = {}) => {
  const roundTripKm = Math.max(Number(communeConfig.roundTripKm) || 0, 0);
  const oneWayMinutes = Math.max(Number(communeConfig.oneWayMinutes) || 0, 0);
  const isOutsideMetropolitana = communeConfig.regionKey !== "metropolitana";
  const isRemoteByDistance =
    roundTripKm >= LOGISTICS_REMOTE_DISTANCE_THRESHOLD_KM;
  const isRemoteByTime =
    isOutsideMetropolitana &&
    oneWayMinutes > LOGISTICS_LODGING_MIN_ONE_WAY_MINUTES;
  const isRemoteProject =
    Boolean(communeConfig.specialLogistics) ||
    isRemoteByDistance ||
    isRemoteByTime;
  const isIntermediateProject =
    !isRemoteProject &&
    oneWayMinutes > LOGISTICS_INTERMEDIATE_MIN_ONE_WAY_MINUTES;
  const logisticsTier = isRemoteProject
    ? "lodging"
    : isIntermediateProject
      ? "intermediate"
      : "local";
  const logisticsLabel = isRemoteProject
    ? "Proyecto con alojamiento"
    : isIntermediateProject
      ? "Logística intermedia"
      : "Logística local";

  return {
    oneWayMinutes,
    isOutsideMetropolitana,
    isRemoteByDistance,
    isRemoteByTime,
    isRemoteProject,
    isIntermediateProject,
    isLongDistanceRemote:
      Boolean(communeConfig.specialLogistics) || isRemoteByDistance,
    logisticsTier,
    logisticsLabel,
  };
};

const getTravelTimeLaborCost = ({
  oneWayMinutes = 0,
  projectWorkDays = 0,
  crewDailyRate = 0,
} = {}) => {
  const dailyRoundTripHours = (Math.max(oneWayMinutes, 0) * 2) / 60;
  const hourlyCrewRate =
    Math.max(crewDailyRate, 0) / LOGISTICS_STANDARD_WORKDAY_HOURS;

  return Math.round(
    dailyRoundTripHours *
      Math.max(projectWorkDays, 0) *
      hourlyCrewRate,
  );
};

const getInstallationWorkDaysFromPanels = (panelCount = 0) => {
  const safePanelCount = Math.max(Math.ceil(Number(panelCount) || 0), 1);
  const panelBasedWorkDays = Math.ceil(
    safePanelCount / INSTALLATION_PANEL_CREW_CAPACITY_PER_DAY,
  );

  return Math.max(INSTALLATION_MIN_WORK_DAYS, panelBasedWorkDays);
};

const getInstallationRemoteBufferDays = (panelCount = 0, roundTripKm = 0) => {
  const safePanelCount = Math.max(Math.ceil(Number(panelCount) || 0), 1);
  const panelBufferDays =
    INSTALLATION_REMOTE_BASE_BUFFER_DAYS +
    Math.ceil(Math.max(safePanelCount - 20, 0) / INSTALLATION_REMOTE_PANEL_BUFFER_BLOCK);
  const distanceBufferDays =
    roundTripKm >= INSTALLATION_REMOTE_DISTANCE_BUFFER_THRESHOLD_KM
      ? Math.ceil(
          (roundTripKm - INSTALLATION_REMOTE_DISTANCE_BUFFER_THRESHOLD_KM + 1) /
            INSTALLATION_REMOTE_DISTANCE_BUFFER_BLOCK_KM,
        )
      : 0;

  return panelBufferDays + distanceBufferDays;
};

const getInstallationProjectLogistics = (communeConfig, panelCount = 0) => {
  const safeCommune = communeConfig || { roundTripKm: 0, tolls: 0 };
  const travelMetrics = getTravelLogisticsBase(
    safeCommune.roundTripKm,
    safeCommune.tolls,
  );
  const logisticsMode = getProjectLogisticsMode(safeCommune);
  const projectWorkDays = getInstallationWorkDaysFromPanels(panelCount);

  if (logisticsMode.isRemoteProject) {
    const travelDays = logisticsMode.isLongDistanceRemote
      ? INSTALLATION_REMOTE_TRAVEL_DAYS
      : 0;
    const bufferDays = getInstallationRemoteBufferDays(
      panelCount,
      safeCommune.roundTripKm,
    );
    const projectCalendarDays = projectWorkDays + travelDays + bufferDays;
    const lodgingNights = Math.max(projectCalendarDays - 1, 1);
    const localLogistics =
      projectCalendarDays * INSTALLATION_LOCAL_LOGISTICS_CLP_PER_DAY;
    const laborDays = projectCalendarDays;
    const laborTotal = laborDays * INSTALLATION_TECH_CREW_LABOR_CLP_PER_DAY;

    return {
      ...travelMetrics,
      ...logisticsMode,
      roundTripKm: safeCommune.roundTripKm,
      tolls: safeCommune.tolls,
      panelCount: Math.max(Math.ceil(Number(panelCount) || 0), 1),
      projectWorkDays,
      travelDays,
      bufferDays,
      projectCalendarDays,
      lodgingDays: lodgingNights,
      lodgingNights,
      localLogistics,
      laborDays,
      laborTotal,
      travelBaseNet: travelMetrics.logisticsBase,
      travelTimeLaborNet: 0,
      logisticsTotal:
        travelMetrics.logisticsBase +
        lodgingNights * INSTALLATION_REMOTE_LODGING_CLP_PER_DAY +
        localLogistics,
    };
  }

  const projectCalendarDays = projectWorkDays;
  const laborDays = projectCalendarDays;
  const laborTotal = laborDays * INSTALLATION_TECH_CREW_LABOR_CLP_PER_DAY;
  const travelTimeLaborNet = logisticsMode.isIntermediateProject
    ? getTravelTimeLaborCost({
        oneWayMinutes: logisticsMode.oneWayMinutes,
        projectWorkDays,
        crewDailyRate: INSTALLATION_TECH_CREW_LABOR_CLP_PER_DAY,
      })
    : 0;
  const travelBaseNet = travelMetrics.logisticsBase * projectWorkDays;

  return {
    ...travelMetrics,
    ...logisticsMode,
    roundTripKm: safeCommune.roundTripKm,
    tolls: safeCommune.tolls,
    panelCount: Math.max(Math.ceil(Number(panelCount) || 0), 1),
    projectWorkDays,
    travelDays: 0,
    bufferDays: 0,
    projectCalendarDays,
    lodgingDays: 0,
    lodgingNights: 0,
    localLogistics: 0,
    laborDays,
    laborTotal,
    travelBaseNet,
    travelTimeLaborNet,
    logisticsTotal: travelBaseNet + travelTimeLaborNet,
  };
};

