const buildQuotationNumber = ({ name, phone, email, date = new Date() }) => {
  const year = String(date.getFullYear());
  const month = String(date.getMonth() + 1).padStart(2, "0");
  const day = String(date.getDate()).padStart(2, "0");
  const source = `${name || ""}-${phone || ""}-${email || ""}-${year}${month}${day}`;
  let hash = 0;

  for (let index = 0; index < source.length; index += 1) {
    hash = (hash * 31 + source.charCodeAt(index)) % 10000;
  }

  return `COT-${year}${month}${day}-${String(hash).padStart(4, "0")}`;
};

const savePdfFile = (pdf, fileName) => {
  if (typeof window === "undefined") return;

  const userAgent = window.navigator?.userAgent || "";
  const isInAppBrowser = /Instagram|FBAN|FBAV|Line|wv/i.test(userAgent);

  if (!isInAppBrowser || typeof pdf.output !== "function") {
    pdf.save(fileName);
    return;
  }

  const pdfBlob = pdf.output("blob");
  const pdfUrl = window.URL.createObjectURL(pdfBlob);
  const link = document.createElement("a");
  link.href = pdfUrl;
  link.download = fileName;
  link.rel = "noopener noreferrer";
  document.body.appendChild(link);
  link.click();
  document.body.removeChild(link);

  window.setTimeout(() => {
    window.URL.revokeObjectURL(pdfUrl);
  }, 30000);
};

const buildReportBarChartMarkup = ({
  title,
  items,
  formatter = (value) => String(value),
}) => {
  const safeItems = items.filter((item) => Number.isFinite(item.value));
  const maxValue = Math.max(...safeItems.map((item) => item.value), 1);

  return `
    <section class="pdf-chart-card">
      <h3>${escapeHtml(title)}</h3>
      <div class="pdf-chart-bars">
        ${safeItems
          .map(
            (item) => `
              <div class="pdf-chart-item">
                <div class="pdf-chart-bar-wrap">
                  <div class="pdf-chart-bar" style="height:${Math.max(
                    (item.value / maxValue) * 148,
                    16,
                  ).toFixed(1)}px"></div>
                </div>
                <strong>${escapeHtml(item.label)}</strong>
                <span>${escapeHtml(formatter(item.value))}</span>
              </div>
            `,
          )
          .join("")}
      </div>
    </section>
  `;
};

const INSTALLATION_CARD_PRICE_FACTOR = 1.0195332372933024;
const INSTALLATION_CARD_FIXED_ADJUSTMENT_CLP = 89.26466448690459;
const INSTALLATION_CARD_INSTALLMENT_OPTIONS = [12, 18, 24, 36];

const getInstallationCardPrice = (cashPrice = 0) => {
  const safeCashPrice = Math.max(Number(cashPrice) || 0, 0);
  if (!safeCashPrice) return 0;

  return (
    safeCashPrice * INSTALLATION_CARD_PRICE_FACTOR +
    INSTALLATION_CARD_FIXED_ADJUSTMENT_CLP
  );
};

const getRecommendedInstallationInstallments = (
  cardPrice = 0,
  monthlyBill = 0,
) => {
  const safeCardPrice = Math.max(Number(cardPrice) || 0, 0);
  const safeMonthlyBill = Math.max(Number(monthlyBill) || 0, 0);

  if (!safeCardPrice || !safeMonthlyBill) {
    return INSTALLATION_CARD_INSTALLMENT_OPTIONS[1];
  }

  return (
    INSTALLATION_CARD_INSTALLMENT_OPTIONS.find(
      (installments) => safeCardPrice / installments <= safeMonthlyBill,
    ) ||
    INSTALLATION_CARD_INSTALLMENT_OPTIONS[
      INSTALLATION_CARD_INSTALLMENT_OPTIONS.length - 1
    ]
  );
};

const getInstallationQuotationItems = (
  metrics,
  selectedOffer,
  paymentSelection = null,
) => {
  const costs = metrics.quotationCosts || {};
  const selectedKey = selectedOffer?.key || "huaweiNoBattery";
  const normalizedSelectedKey = selectedKey.toLowerCase();
  const isHuawei = normalizedSelectedKey.startsWith("huawei");
  const isSolis = normalizedSelectedKey.startsWith("solis");
  const includesBattery = normalizedSelectedKey.includes("withbattery");
  const inverterDescription = isHuawei
    ? "INVERSOR HUAWEI HÍBRIDO 8 KW"
    : isSolis
      ? "INVERSOR SOLIS HÍBRIDO 8 KW"
      : "INVERSOR HÍBRIDO 8 KW";

  const rows = [
    {
      description: "MÓDULOS FOTOVOLTAICOS 585W",
      quantity: metrics.estimatedPanels,
      totalNet: costs.modulesNet,
    },
    {
      description: inverterDescription,
      quantity: 1,
      totalNet: isHuawei ? costs.huaweiInverterNet : costs.solisInverterNet,
    },
    {
      description: "MANO DE OBRA TÉCNICA",
      quantity: 1,
      totalNet: costs.laborNet,
    },
    {
      description: metrics.isRemoteProject
        ? "LOGÍSTICA, TRASLADOS Y ALOJAMIENTO"
        : metrics.isIntermediateProject
          ? "LOGÍSTICA INTERMEDIA Y TRASLADOS"
          : "LOGÍSTICA DEL PROYECTO",
      quantity: 1,
      totalNet: costs.logisticsNet,
    },
    {
      description: "CABLEADO CORRIENTE CONTINUA",
      quantity: 1,
      totalNet: costs.ccCablingNet,
    },
    {
      description: "CABLEADO ALTERNA Y TABLERO",
      quantity: 1,
      totalNet: costs.acBoardNet,
    },
    {
      description: "CERTIFICACIÓN SEC",
      quantity: 1,
      totalNet: costs.certSecNet,
    },
    {
      description: "SEÑALÉTICAS",
      quantity: 1,
      totalNet: costs.signageNet,
    },
  ];

  if (isHuawei && costs.huaweiSmartPowerSensorNet > 0) {
    rows.push({
      description: "SMART POWER SENSOR",
      quantity: 1,
      totalNet: costs.huaweiSmartPowerSensorNet,
    });
  }

  if (includesBattery) {
    rows.push({
      description: isHuawei
        ? "SISTEMA DE BATERÍA HUAWEI LUNA"
        : "SISTEMA DE BATERÍA SOLIS / DYNESS",
      quantity: 1,
      totalNet: isHuawei ? costs.huaweiBatteryPackNet : costs.solisBatteryPackNet,
    });
  }

  rows.push({
    description: "ESTRUCTURA PARA MÓDULOS",
    quantity: metrics.structureBlocks,
    totalNet: costs.structureNet,
  });

  const baseRows = rows.filter(
    (row) => Number.isFinite(row.totalNet) && row.totalNet > 0,
  );
  const baseNet = baseRows.reduce((sum, row) => sum + row.totalNet, 0);
  const targetGross = Math.max(
    Number(paymentSelection?.finalPrice) || baseNet * 1.19,
    0,
  );
  const targetNet = targetGross / 1.19;
  const priceScale = baseNet > 0 ? targetNet / baseNet : 1;

  return baseRows.map((row, index) => ({
    ...row,
    item: index + 1,
    totalNet: row.totalNet * priceScale,
  }));
};

